'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import {
  LayoutDashboard,
  ScanLine,
  FileText,
  Puzzle,
  Settings,
  Zap,
  TrendingUp,
  Swords,
  Code2,
  Gift,
  Activity,
  Search,
} from 'lucide-react'
import { Progress } from '@/components/ui/progress'
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarFooter,
  SidebarHeader,
  useSidebar,
} from '@/components/ui/sidebar'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { useAuth } from '@/contexts/AuthContext'
import { useFeatureFlag } from '@/hooks/use-feature-flag'
import { useTeams } from '@/hooks/use-teams'
import { TeamSwitcher } from '@/components/team/TeamSwitcher'
import { isProPlus } from '@/types/index'
import { cn } from '@/lib/utils'

interface NavItem {
  title: string
  url: string
  icon: React.ElementType
  flagKey?: string
  proOnly?: boolean
}

interface NavGroup {
  label: string
  items: NavItem[]
}

const NAV_GROUPS: NavGroup[] = [
  {
    label: 'Workspace',
    items: [
      { title: 'Dashboard', url: '/dashboard', icon: LayoutDashboard },
      { title: 'New Scan', url: '/scan', icon: ScanLine },
    ],
  },
  {
    label: 'Analyze',
    items: [
      { title: 'My Reports', url: '/reports', icon: FileText },
      { title: 'Score History', url: '/history', icon: TrendingUp },
      { title: 'Competitors', url: '/competitors', icon: Swords },
    ],
  },
  {
    label: 'Manage',
    items: [
      { title: 'Integrations', url: '/integrations', icon: Puzzle, flagKey: 'integrations_enabled' },
      { title: 'Monitoring', url: '/monitoring', icon: Activity, proOnly: true },
    ],
  },
  {
    label: 'Account',
    items: [
      { title: 'Refer & Earn', url: '/referrals', icon: Gift },
      { title: 'API', url: '/api-settings', icon: Code2, proOnly: true },
      { title: 'Settings', url: '/settings', icon: Settings },
    ],
  },
]

function openCommandPalette() {
  window.dispatchEvent(
    new KeyboardEvent('keydown', { key: 'k', metaKey: true, bubbles: true })
  )
}

export function AppSidebar() {
  const { state } = useSidebar()
  const collapsed = state === 'collapsed'
  const pathname = usePathname()
  const { profile } = useAuth()
  const { data: teams } = useTeams()
  const showTeamSwitcher =
    !collapsed && profile && isProPlus(profile.plan) && (teams?.length ?? 0) >= 0

  const integrationsEnabled = useFeatureFlag('integrations_enabled', true)

  const isActive = (path: string) =>
    pathname === path || pathname.startsWith(path + '/')

  const filterItems = (items: NavItem[]) =>
    items.filter((item) => {
      if (item.flagKey === 'integrations_enabled') return integrationsEnabled
      if (item.proOnly && profile) return isProPlus(profile.plan)
      return true
    })

  const scansUsed = profile?.scans_used ?? 0
  const scanLimit = profile?.scan_limit ?? 3
  const usagePercent = scanLimit > 0 ? Math.round((scansUsed / scanLimit) * 100) : 0
  const planLabel = profile?.plan ?? 'free'
  const isUnlimited = planLabel === 'agency' || planLabel === 'pro'
  const showUpgrade = !isUnlimited

  return (
    <Sidebar collapsible="icon" className="border-r-0" aria-label="Main navigation">
      <SidebarHeader className="px-4 py-5 group-data-[collapsible=icon]:px-2 group-data-[collapsible=icon]:py-4 group-data-[collapsible=icon]:items-center">
        <Link
          href="/dashboard"
          className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-full"
        >
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-sidebar-primary shrink-0">
            <ScanLine className="h-3.5 w-3.5 text-white" />
          </div>
          {!collapsed && (
            <span className="text-base font-semibold tracking-tight text-[--sidebar-foreground-active]">
              ConvertScan
            </span>
          )}
        </Link>
        {showTeamSwitcher && (
          <div className="mt-3 -mx-1">
            <TeamSwitcher />
          </div>
        )}
      </SidebarHeader>

      <SidebarContent className="px-2 group-data-[collapsible=icon]:px-1">
        {NAV_GROUPS.map((group, gi) => {
          const visibleItems = filterItems(group.items)
          if (visibleItems.length === 0) return null

          return (
            <SidebarGroup key={gi}>
              {!collapsed && (
                <SidebarGroupLabel className="text-[10px] font-medium uppercase tracking-wider text-sidebar-foreground/50 px-3 py-1.5 mt-2">
                  {group.label}
                </SidebarGroupLabel>
              )}
              <SidebarGroupContent>
                <SidebarMenu className="space-y-0.5">
                  {visibleItems.map((item) => {
                    const active = isActive(item.url)
                    return (
                      <SidebarMenuItem key={item.title}>
                        <SidebarMenuButton
                          asChild
                          tooltip={item.title}
                          isActive={active}
                          className={cn(
                            'h-9 transition-colors duration-150 rounded-md',
                            active
                              ? 'bg-[--sidebar-item-active-bg] text-[--sidebar-foreground-active]'
                              : 'text-sidebar-foreground hover:bg-[--sidebar-item-hover-bg] hover:text-[--sidebar-foreground-active]'
                          )}
                        >
                          <Link href={item.url}>
                            <item.icon
                              className={cn(
                                'h-4 w-4 shrink-0',
                                active
                                  ? 'text-[--sidebar-foreground-active]'
                                  : 'text-sidebar-foreground/60'
                              )}
                            />
                            <span className="text-sm font-medium">{item.title}</span>
                          </Link>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    )
                  })}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          )
        })}
      </SidebarContent>

      <SidebarFooter className="p-3 group-data-[collapsible=icon]:p-2 group-data-[collapsible=icon]:items-center">
        {/* Footer card — expanded */}
        {!collapsed && (
          <>
            <div className="rounded-lg border border-sidebar-border p-3 mb-0">
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-medium text-sidebar-foreground capitalize">
                  {planLabel} plan
                </span>
                {!isUnlimited && (
                  <span className="text-xs font-medium text-sidebar-foreground tabular-nums">
                    {scansUsed}/{scanLimit} scans
                  </span>
                )}
              </div>
              {!isUnlimited && (
                <Progress value={usagePercent} className="h-1 mb-3" />
              )}
              {showUpgrade && (
                <Link
                  href="/pricing"
                  className="flex items-center justify-center gap-2 w-full rounded-md bg-sidebar-primary px-3 py-2 text-sm font-semibold text-white transition-opacity hover:opacity-90"
                >
                  <Zap className="h-4 w-4" />
                  Upgrade Plan
                </Link>
              )}
            </div>

            {/* ⌘K hint row */}
            <button
              type="button"
              onClick={openCommandPalette}
              className="mt-2 flex items-center w-full rounded-md bg-sidebar-accent/50 px-3 h-8 transition-colors hover:bg-sidebar-accent"
            >
              <Search className="h-3.5 w-3.5 text-sidebar-foreground/50 shrink-0 mr-2" />
              <span className="flex-1 text-left text-xs text-sidebar-foreground/70">
                Search...
              </span>
              <kbd className="text-[10px] text-sidebar-foreground/50 font-mono">
                ⌘K
              </kbd>
            </button>
          </>
        )}

        {/* Collapsed footer — icon pill with tooltip */}
        {collapsed && (
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                {showUpgrade ? (
                  <Link
                    href="/pricing"
                    aria-label="Upgrade Plan"
                    className="flex h-10 w-10 items-center justify-center rounded-md bg-sidebar-primary text-white transition-opacity hover:opacity-90"
                  >
                    <Zap className="h-4 w-4" />
                  </Link>
                ) : (
                  <div
                    aria-label={`${planLabel} plan`}
                    className="flex h-10 w-10 items-center justify-center rounded-md bg-sidebar-accent text-sidebar-foreground/70 cursor-default"
                  >
                    <Zap className="h-4 w-4" />
                  </div>
                )}
              </TooltipTrigger>
              <TooltipContent side="right" className="text-xs">
                {isUnlimited
                  ? `${planLabel} plan — unlimited`
                  : `${planLabel} · ${scansUsed}/${scanLimit} scans`}
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        )}
      </SidebarFooter>
    </Sidebar>
  )
}
